head.script:
/**
 * squeeze 모드 테스트 레이아웃
 * 논리 4x4 → 실제 24x24 (splitCnt=6)
 *
 *  논리 Col:  0     1     2     3
 *  ┌─────┬───────────┬─────┐
 *  │  A  │     B     │  C  │  Row 0
 *  ├─────┴─────┬─────┼─────┤
 *  │     D     │  E  │  F  │  Row 1
 *  ├───────────┼─────┴─────┤
 *  │           │           │  Row 2
 *  │     G     │     H     │
 *  │           │           │  Row 3
 *  └───────────┴───────────┘
 */
var S = 6; // splitCnt: 논리 1칸 = 실제 6유닛

scwin.onpageload = function() {
    // Row 0: [A:1x1] [B:2x1] [C:1x1]
    widgetContainer.addWidgets({id:"A", title:"A (1x1)", src:"widgetContainer_dragdrop_WAEA-595_(WSQ-6225)_black.xml", scope:true, x:0*S, y:0*S, unitWidth:1*S, unitHeight:1*S});
    widgetContainer.addWidgets({id:"B", title:"B (2x1)", src:"widgetContainer_dragdrop_WAEA-595_(WSQ-6225)_red.xml",   scope:true, x:1*S, y:0*S, unitWidth:2*S, unitHeight:1*S});
    widgetContainer.addWidgets({id:"C", title:"C (1x1)", src:"widgetContainer_dragdrop_WAEA-595_(WSQ-6225)_blue.xml",  scope:true, x:3*S, y:0*S, unitWidth:1*S, unitHeight:1*S});
    // Row 1: [D:2x1] [E:1x1] [F:1x1]
    widgetContainer.addWidgets({id:"D", title:"D (2x1)", src:"widgetContainer_dragdrop_WAEA-595_(WSQ-6225)_red.xml",   scope:true, x:0*S, y:1*S, unitWidth:2*S, unitHeight:1*S});
    widgetContainer.addWidgets({id:"E", title:"E (1x1)", src:"widgetContainer_dragdrop_WAEA-595_(WSQ-6225)_black.xml", scope:true, x:2*S, y:1*S, unitWidth:1*S, unitHeight:1*S});
    widgetContainer.addWidgets({id:"F", title:"F (1x1)", src:"wwidgetContainer_dragdrop_WAEA-595_(WSQ-6225)_blue.xml",  scope:true, x:3*S, y:1*S, unitWidth:1*S, unitHeight:1*S});
    // Rows 2-3: [G:2x2] [H:2x2]
    widgetContainer.addWidgets({id:"G", title:"G (2x2)", src:"widgetContainer_dragdrop_WAEA-595_(WSQ-6225)_blue.xml",  scope:true, x:0*S, y:2*S, unitWidth:2*S, unitHeight:2*S});
    widgetContainer.addWidgets({id:"H", title:"H (2x2)", src:"widgetContainer_dragdrop_WAEA-595_(WSQ-6225)_black.xml", scope:true, x:2*S, y:2*S, unitWidth:2*S, unitHeight:2*S});
};

var count = 0;
scwin.trigger1_onclick = function(e) {
    count++;
    widgetContainer.addWidgets({
        id: "W" + count,
        title: "Added_" + count,
        scope: true,
        x: 0, y: 0,
        unitWidth: 1, unitHeight: 1
    });
};
